input.command:
npm install postmark 2>&1 | tail -2
mkdir -p src/lib
cat > src/lib/postmark.ts <<'EOF'
import { ServerClient } from "postmark";

// Server-only: never import this from client components.
export const postmark = new ServerClient(process.env.POSTMARK_SERVER_TOKEN ?? "");
EOF
cat > src/lib/email.ts <<'EOF'
import { postmark } from "@/lib/postmark";
import type { User } from "@/lib/users";

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

async function send(to: string, subject: string, html: string, text: string) {
  try {
    await postmark.sendEmail({
      From: process.env.POSTMARK_FROM_EMAIL!,
      To: to,
      Subject: subject,
      HtmlBody: html,
      TextBody: text,
      MessageStream: process.env.POSTMARK_MESSAGE_STREAM ?? "outbound",
    });
  } catch (err) {
    // A failed email must not break the request that triggered it.
    console.error("Failed to send email", { subject, error: err });
  }
}

export async function sendWelcomeEmail(user: User) {
  const name = escapeHtml(user.name);
  await send(
    user.email,
    "Welcome to Notely",
    `<p>Hi ${name},</p><p>Welcome to Notely — your team's notes are ready.</p>`,
    `Hi ${user.name},\n\nWelcome to Notely — your team's notes are ready.`,
  );
}

export async function sendPasswordResetEmail(user: User, resetUrl: string) {
  const name = escapeHtml(user.name);
  const url = escapeHtml(resetUrl);
  await send(
    user.email,
    "Reset your Notely password",
    `<p>Hi ${name},</p><p><a href="${url}">Reset your password</a>. This link expires in 1 hour.</p><p>If you didn't ask for this, you can ignore this email.</p>`,
    `Hi ${user.name},\n\nReset your password: ${resetUrl}\nThis link expires in 1 hour.\n\nIf you didn't ask for this, you can ignore this email.`,
  );
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// In-memory like the users list; keyed by SHA-256 of the token so raw tokens are never stored.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  // Resolve silently for unknown emails so callers can't enumerate accounts.
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  const base = process.env.APP_URL ?? "http://localhost:3000";
  await sendPasswordResetEmail(user, `${base}/reset-password?token=${token}`);
}

// Returns the user the token belongs to and consumes it, or undefined if invalid/expired.
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
EOF
